export interface AnalysisResult {
  score: number; // 0-100 (100 = Highly likely Real, 0 = Highly likely Fake)
  verdict: 'REAL' | 'FAKE' | 'UNCERTAIN';
  summary: string;
  artifacts: string[]; // List of specific visual artifacts found
  technicalMetrics: {
    lightingConsistency: number; // 0-10
    textureNaturalness: number; // 0-10
    anatomyCorrectness: number; // 0-10
    backgroundCoherence: number; // 0-10
  };
  reasoning: string;
}

export interface AnalysisHistoryItem {
  id: string;
  thumbnail: string;
  timestamp: number;
  result: AnalysisResult;
}

export enum AppState {
  IDLE,
  ANALYZING,
  RESULT,
  ERROR
}

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeMediaIntegrity = async (base64Image: string): Promise<AnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image
            }
          },
          {
            text: `Analyze this image strictly for signs of digital manipulation, deepfake synthesis, or generative AI origin.

            Look for:
            1. Inconsistent lighting and shadows.
            2. Unnatural skin textures (too smooth, plasticky).
            3. Asymmetry in facial features (eyes, ears, glasses).
            4. Background warping or nonsensical details.
            5. Digital artifacts around edges.

            Provide a forensic integrity score where 0 is definitely FAKE/AI and 100 is definitely REAL/AUTHENTIC.
            `
          }
        ]
      },
      config: {
        systemInstruction: "You are a senior digital forensics expert specializing in AI-generated media detection. Your analysis is technical, objective, and precise.",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER, description: "0 to 100, where 100 is authentic." },
            verdict: { type: Type.STRING, enum: ["REAL", "FAKE", "UNCERTAIN"] },
            summary: { type: Type.STRING },
            artifacts: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "List of specific visual anomalies detected."
            },
            technicalMetrics: {
              type: Type.OBJECT,
              properties: {
                lightingConsistency: { type: Type.NUMBER, description: "0-10 score" },
                textureNaturalness: { type: Type.NUMBER, description: "0-10 score" },
                anatomyCorrectness: { type: Type.NUMBER, description: "0-10 score" },
                backgroundCoherence: { type: Type.NUMBER, description: "0-10 score" }
              },
              required: ["lightingConsistency", "textureNaturalness", "anatomyCorrectness", "backgroundCoherence"]
            },
            reasoning: { type: Type.STRING }
          },
          required: ["score", "verdict", "summary", "artifacts", "technicalMetrics", "reasoning"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text) as AnalysisResult;
  } catch (error) {
    console.error("Deepfake analysis failed:", error);
    throw error;
  }
};

