import React from 'react';
import { AnalysisResult } from '../types';
import { ShieldCheck, ShieldAlert, AlertTriangle, Activity, Eye, Zap, Layers, Image as ImageIcon } from 'lucide-react';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, ResponsiveContainer } from 'recharts';

interface ResultsDashboardProps {
  result: AnalysisResult;
  onReset: () => void;
}

const ResultsDashboard: React.FC<ResultsDashboardProps> = ({ result, onReset }) => {
  const isReal = result.verdict === 'REAL';
  const isFake = result.verdict === 'FAKE';

  const chartData = [
    { subject: 'Lighting', A: result.technicalMetrics.lightingConsistency, fullMark: 10 },
    { subject: 'Texture', A: result.technicalMetrics.textureNaturalness, fullMark: 10 },
    { subject: 'Anatomy', A: result.technicalMetrics.anatomyCorrectness, fullMark: 10 },
    { subject: 'Background', A: result.technicalMetrics.backgroundCoherence, fullMark: 10 },
  ];

  return (
    <div className="w-full max-w-4xl mx-auto space-y-6 animate-fade-in">

      {/* Main Verdict Banner */}
      <div className={`relative overflow-hidden rounded-2xl border p-8 flex flex-col md:flex-row items-center justify-between gap-6 ${
        isReal 
          ? 'bg-accent-600/10 border-accent-500/50 shadow-[0_0_30px_rgba(16,185,129,0.2)]' 
          : isFake 
            ? 'bg-danger-600/10 border-danger-500/50 shadow-[0_0_30px_rgba(239,68,68,0.2)]'
            : 'bg-yellow-600/10 border-yellow-500/50'
      }`}>
        <div className="flex items-center gap-4 z-10">
          <div className={`p-4 rounded-full ${isReal ? 'bg-accent-500/20' : isFake ? 'bg-danger-500/20' : 'bg-yellow-500/20'}`}>
            {isReal && <ShieldCheck className="w-12 h-12 text-accent-500" />}
            {isFake && <ShieldAlert className="w-12 h-12 text-danger-500" />}
            {!isReal && !isFake && <AlertTriangle className="w-12 h-12 text-yellow-500" />}
          </div>
          <div>
            <h2 className="text-sm font-mono uppercase tracking-widest text-gray-400 mb-1">Integrity Verdict</h2>
            <h1 className={`text-4xl font-bold tracking-tight ${
              isReal ? 'text-accent-400' : isFake ? 'text-danger-400' : 'text-yellow-400'
            }`}>
              {result.verdict}
            </h1>
          </div>
        </div>

        <div className="flex flex-col items-center md:items-end z-10">
            <div className="text-sm font-mono text-gray-400 uppercase mb-1">Authenticity Score</div>
            <div className={`text-5xl font-bold font-mono ${
                 result.score > 80 ? 'text-accent-400' : result.score < 50 ? 'text-danger-400' : 'text-yellow-400'
            }`}>
                {result.score}%
            </div>
        </div>

        {/* Background gradient splash */}
        <div className={`absolute -right-20 -top-20 w-64 h-64 rounded-full blur-[80px] opacity-30 ${
           isReal ? 'bg-accent-500' : isFake ? 'bg-danger-500' : 'bg-yellow-500'
        }`}></div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Detail Analysis */}
        <div className="glass-panel p-6 rounded-2xl flex flex-col">
          <h3 className="text-xl font-semibold mb-6 flex items-center gap-2">
            <Activity className="w-5 h-5 text-brand-500" />
            Analysis Summary
          </h3>
          <p className="text-gray-300 leading-relaxed mb-6">
            {result.summary}
          </p>

          <div className="space-y-4 mt-auto">
             <h4 className="text-sm font-mono text-gray-500 uppercase">Detected Artifacts</h4>
             <ul className="space-y-2">
                {result.artifacts.length > 0 ? (
                    result.artifacts.map((artifact, idx) => (
                        <li key={idx} className="flex items-start gap-2 text-sm text-gray-300">
                            <span className="text-danger-500 mt-0.5">●</span>
                            {artifact}
                        </li>
                    ))
                ) : (
                    <li className="text-sm text-gray-500 italic">No significant artifacts detected.</li>
                )}
             </ul>
          </div>
        </div>

        {/* Metrics Chart */}
        <div className="glass-panel p-6 rounded-2xl flex flex-col items-center justify-center min-h-[300px]">
           <h3 className="text-xl font-semibold mb-2 self-start flex items-center gap-2">
            <Layers className="w-5 h-5 text-brand-500" />
            Technical Metrics
          </h3>
          <div className="w-full h-[250px] relative">
            <ResponsiveContainer width="100%" height="100%">
              <RadarChart cx="50%" cy="50%" outerRadius="80%" data={chartData}>
                <PolarGrid stroke="#374151" />
                <PolarAngleAxis dataKey="subject" tick={{ fill: '#9ca3af', fontSize: 12 }} />
                <Radar
                  name="Metrics"
                  dataKey="A"
                  stroke={isReal ? '#10b981' : '#ef4444'}
                  fill={isReal ? '#10b981' : '#ef4444'}
                  fillOpacity={0.3}
                />
              </RadarChart>
            </ResponsiveContainer>
          </div>
          <div className="grid grid-cols-2 w-full gap-4 mt-4">
              <MetricBadge icon={<Zap size={16} />} label="Lighting" value={result.technicalMetrics.lightingConsistency} />
              <MetricBadge icon={<ImageIcon size={16} />} label="Texture" value={result.technicalMetrics.textureNaturalness} />
              <MetricBadge icon={<Eye size={16} />} label="Anatomy" value={result.technicalMetrics.anatomyCorrectness} />
              <MetricBadge icon={<Layers size={16} />} label="Background" value={result.technicalMetrics.backgroundCoherence} />
          </div>
        </div>
      </div>

      <div className="glass-panel p-6 rounded-2xl">
        <h3 className="text-sm font-mono text-gray-500 uppercase mb-3">AI Reasoning Chain</h3>
        <p className="text-sm text-gray-300 font-mono bg-black/30 p-4 rounded-lg border border-white/5">
            {result.reasoning}
        </p>
      </div>

      <div className="flex justify-center pt-6 pb-12">
        <button 
          onClick={onReset}
          className="px-8 py-3 bg-brand-600 hover:bg-brand-500 text-white rounded-full font-medium transition-colors shadow-lg shadow-brand-900/50 flex items-center gap-2"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
          Analyze Another Image
        </button>
      </div>
    </div>
  );
};

const MetricBadge = ({ icon, label, value }: { icon: React.ReactNode, label: string, value: number }) => (
    <div className="flex items-center justify-between bg-white/5 p-2 rounded-lg">
        <div className="flex items-center gap-2 text-gray-400 text-xs">
            {icon}
            <span>{label}</span>
        </div>
        <span className={`font-mono font-bold ${value < 5 ? 'text-danger-400' : 'text-accent-400'}`}>{value}/10</span>
    </div>
)

export default ResultsDashboard;

import React, { useRef, useState } from 'react';
import { Upload, FileImage, Camera } from 'lucide-react';

interface DropzoneProps {
  onFileSelect: (file: File) => void;
  onCameraSelect: () => void;
}

const Dropzone: React.FC<DropzoneProps> = ({ onFileSelect, onCameraSelect }) => {
  const [isDragActive, setIsDragActive] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragActive(true);
  };

  const handleDragLeave = () => {
    setIsDragActive(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      validateAndPassFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      validateAndPassFile(e.target.files[0]);
    }
  };

  const validateAndPassFile = (file: File) => {
    if (!file.type.startsWith('image/')) {
        alert("Please upload an image file.");
        return;
    }
    onFileSelect(file);
  }

  return (
    <div className="w-full max-w-2xl mx-auto">
      <div 
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        className={`
            relative group
            border-2 border-dashed rounded-3xl p-12
            flex flex-col items-center justify-center text-center
            transition-all duration-300 ease-in-out
            cursor-pointer
            ${isDragActive 
                ? 'border-brand-500 bg-brand-500/10 scale-102' 
                : 'border-gray-700 hover:border-brand-500/50 hover:bg-brand-900/10 bg-gray-900/50'
            }
        `}
        onClick={() => inputRef.current?.click()}
      >
        <input 
          type="file" 
          ref={inputRef} 
          onChange={handleFileInput} 
          className="hidden" 
          accept="image/*"
        />

        <div className={`
            w-20 h-20 rounded-full flex items-center justify-center mb-6
            transition-colors duration-300
            ${isDragActive ? 'bg-brand-500 text-white' : 'bg-gray-800 text-brand-500 group-hover:bg-brand-900 group-hover:text-brand-400'}
        `}>
          <Upload size={32} />
        </div>

        <h3 className="text-2xl font-semibold text-white mb-2">
            Upload Image to Analyze
        </h3>
        <p className="text-gray-400 max-w-sm mx-auto mb-8">
            Drag and drop your file here, or click to browse. Supported formats: JPG, PNG, WEBP.
        </p>

        <div className="flex gap-4">
             <button 
                type="button"
                className="px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-sm text-gray-300 flex items-center gap-2 transition-colors"
                onClick={(e) => { e.stopPropagation(); inputRef.current?.click(); }}
             >
                <FileImage size={16} />
                Select File
             </button>
             <button 
                type="button"
                className="px-4 py-2 bg-brand-600/20 hover:bg-brand-600/30 border border-brand-500/30 rounded-lg text-sm text-brand-300 flex items-center gap-2 transition-colors"
                onClick={(e) => { e.stopPropagation(); onCameraSelect(); }}
             >
                <Camera size={16} />
                Use Camera
             </button>
        </div>
      </div>

      <div className="mt-8 flex justify-center gap-8 text-xs text-gray-500 uppercase tracking-widest font-mono">
        <div className="flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-brand-500"></div>
            Private
        </div>
        <div className="flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-brand-500"></div>
            Encrypted
        </div>
        <div className="flex items-center gap-2">
            <div className="w-1.5 h-1.5 rounded-full bg-brand-500"></div>
            Fast Analysis
        </div>
      </div>
    </div>
  );
};

export default Dropzone;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import Dropzone from './components/Dropzone';
import ResultsDashboard from './components/ResultsDashboard';
import ScanningOverlay from './components/ScanningOverlay';
import { analyzeMediaIntegrity } from './services/geminiService';
import { AppState, AnalysisResult } from './types';
import { Aperture, Github, X } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [showCamera, setShowCamera] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // File processing
  const processFile = useCallback((file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      if (e.target?.result) {
        const base64 = e.target.result as string;
        setSelectedImage(base64);
        runAnalysis(base64.split(',')[1]); // Remove data:image/type;base64,
      }
    };
    reader.readAsDataURL(file);
  }, []);

  // Analysis Logic
  const runAnalysis = async (base64Data: string) => {
    setAppState(AppState.ANALYZING);
    setErrorMsg(null);
    try {
      const data = await analyzeMediaIntegrity(base64Data);
      setResult(data);
      setAppState(AppState.RESULT);
    } catch (err) {
      console.error(err);
      setErrorMsg("Analysis failed. Please try again or use a different image.");
      setAppState(AppState.ERROR);
    }
  };

  const handleReset = () => {
    setAppState(AppState.IDLE);
    setSelectedImage(null);
    setResult(null);
    setErrorMsg(null);
  };

  // Camera Handling
  const startCamera = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      console.error("Camera access denied:", err);
      alert("Could not access camera.");
      setShowCamera(false);
    }
  };

  const stopCamera = () => {
     if (videoRef.current && videoRef.current.srcObject) {
         const stream = videoRef.current.srcObject as MediaStream;
         stream.getTracks().forEach(track => track.stop());
         videoRef.current.srcObject = null;
     }
     setShowCamera(false);
  };

  const capturePhoto = () => {
      if (videoRef.current && canvasRef.current) {
          const video = videoRef.current;
          const canvas = canvasRef.current;
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          if (ctx) {
              ctx.drawImage(video, 0, 0);
              const base64 = canvas.toDataURL('image/jpeg');
              setSelectedImage(base64);
              stopCamera();
              runAnalysis(base64.split(',')[1]);
          }
      }
  };

  return (
    <div className="min-h-screen bg-black text-gray-100 font-sans selection:bg-brand-500/30">

      {/* Background Ambience */}
      <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none">
        <div className="absolute top-0 left-1/4 w-[500px] h-[500px] bg-brand-900/20 rounded-full blur-[100px] mix-blend-screen animate-pulse-slow"></div>
        <div className="absolute bottom-0 right-1/4 w-[600px] h-[600px] bg-indigo-900/20 rounded-full blur-[120px] mix-blend-screen animate-pulse-slow" style={{ animationDelay: '1s' }}></div>
      </div>

      {/* Header */}
      <nav className="relative z-10 border-b border-white/10 bg-black/50 backdrop-blur-md">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-brand-500 p-2 rounded-lg">
                <Aperture className="text-white w-6 h-6" />
            </div>
            <span className="text-xl font-bold tracking-tight text-white">TrueSight<span className="text-brand-500">.ai</span></span>
          </div>
          <div className="flex items-center gap-6">
            <a href="#" className="text-sm font-medium text-gray-400 hover:text-white transition-colors">Documentation</a>
            <a href="#" className="text-sm font-medium text-gray-400 hover:text-white transition-colors">API</a>
            <div className="h-4 w-px bg-gray-800"></div>
            <a href="#" className="text-gray-400 hover:text-white transition-colors">
                <Github className="w-5 h-5" />
            </a>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="relative z-10 px-6 py-12 md:py-20 flex flex-col items-center min-h-[calc(100vh-64px)]">

        {appState === AppState.IDLE && (
           <div className="w-full max-w-4xl mx-auto animate-fade-in text-center">
              <div className="inline-block px-4 py-1.5 rounded-full border border-brand-500/30 bg-brand-500/10 text-brand-300 text-sm font-medium mb-8">
                Powered by Gemini 1.5 Pro Vision
              </div>
              <h1 className="text-5xl md:text-7xl font-bold text-white mb-6 tracking-tight">
                Detect <span className="text-transparent bg-clip-text bg-gradient-to-r from-brand-400 to-indigo-500">Deepfakes</span><br/>
                with Precision.
              </h1>
              <p className="text-xl text-gray-400 mb-12 max-w-2xl mx-auto leading-relaxed">
                Analyze media integrity using advanced multimodal AI. 
                Identify digital manipulation, synthetic textures, and lighting anomalies in seconds.
              </p>

              <Dropzone onFileSelect={processFile} onCameraSelect={startCamera} />
           </div>
        )}

        {appState === AppState.ANALYZING && selectedImage && (
            <div className="flex flex-col items-center w-full max-w-2xl animate-fade-in">
                <h2 className="text-3xl font-bold mb-8">Analyzing Media Integrity</h2>
                <div className="relative w-full aspect-square md:aspect-video rounded-2xl overflow-hidden border border-white/10 shadow-2xl bg-gray-900">
                    <img src={selectedImage} alt="Analysis Target" className="w-full h-full object-contain opacity-50" />
                    <ScanningOverlay />
                </div>
                <div className="mt-8 space-y-2 text-center">
                    <div className="text-brand-400 font-mono text-sm">PROCESS_ID: {Math.random().toString(36).substring(7).toUpperCase()}</div>
                    <div className="text-gray-500 text-xs">Performing forensic lighting analysis...</div>
                </div>
            </div>
        )}

        {appState === AppState.RESULT && result && (
            <ResultsDashboard result={result} onReset={handleReset} />
        )}

        {appState === AppState.ERROR && (
            <div className="text-center">
                <div className="text-danger-500 text-6xl mb-4">⚠️</div>
                <h2 className="text-2xl font-bold text-white mb-2">Analysis Failed</h2>
                <p className="text-gray-400 mb-6">{errorMsg}</p>
                <button onClick={handleReset} className="text-brand-400 hover:text-brand-300 underline">Try Again</button>
            </div>
        )}

      </main>

      {/* Camera Modal */}
      {showCamera && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4">
            <div className="bg-gray-900 border border-gray-800 rounded-2xl overflow-hidden max-w-2xl w-full relative shadow-2xl">
                <div className="p-4 border-b border-gray-800 flex justify-between items-center">
                    <h3 className="font-semibold text-white">Capture Image</h3>
                    <button onClick={stopCamera} className="text-gray-400 hover:text-white"><X size={20} /></button>
                </div>
                <div className="relative aspect-video bg-black">
                    <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover"></video>
                    <canvas ref={canvasRef} className="hidden"></canvas>
                </div>
                <div className="p-6 flex justify-center bg-gray-900">
                    <button 
                        onClick={capturePhoto} 
                        className="w-16 h-16 rounded-full border-4 border-white flex items-center justify-center hover:bg-white/10 transition-colors"
                    >
                        <div className="w-12 h-12 bg-white rounded-full"></div>
                    </button>
                </div>
            </div>
        </div>
      )}

    </div>
  );
};

