import React, { useState, useCallback, useRef } from 'react';
import Dropzone from './components/Dropzone';
import ResultsDashboard from './components/ResultsDashboard';
import ScanningOverlay from './components/ScanningOverlay';
import { analyzeMediaIntegrity } from './services/geminiService';
import { AppState, AnalysisResult } from './types';
import { Aperture, Github, X, Sparkles } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [showCamera, setShowCamera] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // File processing
  const processFile = useCallback((file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      if (e.target?.result) {
        const base64 = e.target.result as string;
        setSelectedImage(base64);
        runAnalysis(base64.split(',')[1]); // Remove data:image/type;base64,
      }
    };
    reader.readAsDataURL(file);
  }, []);

  // Analysis Logic
  const runAnalysis = async (base64Data: string) => {
    setAppState(AppState.ANALYZING);
    setErrorMsg(null);
    try {
      const data = await analyzeMediaIntegrity(base64Data);
      setResult(data);
      setAppState(AppState.RESULT);
    } catch (err) {
      console.error(err);
      setErrorMsg("Analysis failed. Please ensure the image is valid and try again.");
      setAppState(AppState.ERROR);
    }
  };

  const handleReset = () => {
    setAppState(AppState.IDLE);
    setSelectedImage(null);
    setResult(null);
    setErrorMsg(null);
  };

  // Camera Handling
  const startCamera = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      console.error("Camera access denied:", err);
      alert("Could not access camera. Please allow permissions.");
      setShowCamera(false);
    }
  };

  const stopCamera = () => {
     if (videoRef.current && videoRef.current.srcObject) {
         const stream = videoRef.current.srcObject as MediaStream;
         stream.getTracks().forEach(track => track.stop());
         videoRef.current.srcObject = null;
     }
     setShowCamera(false);
  };

  const capturePhoto = () => {
      if (videoRef.current && canvasRef.current) {
          const video = videoRef.current;
          const canvas = canvasRef.current;
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          if (ctx) {
              ctx.drawImage(video, 0, 0);
              const base64 = canvas.toDataURL('image/jpeg');
              setSelectedImage(base64);
              stopCamera();
              runAnalysis(base64.split(',')[1]);
          }
      }
  };

  return (
    <div className="min-h-screen text-gray-100 font-sans selection:bg-brand-500/30">

      {/* Background Ambience */}
      <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none">
        <div className="absolute top-0 left-1/4 w-[500px] h-[500px] bg-brand-900/10 rounded-full blur-[100px] mix-blend-screen animate-pulse-slow"></div>
        <div className="absolute bottom-0 right-1/4 w-[600px] h-[600px] bg-indigo-900/10 rounded-full blur-[120px] mix-blend-screen animate-pulse-slow" style={{ animationDelay: '2s' }}></div>
      </div>

      {/* Header */}
      <nav className="relative z-10 border-b border-white/5 bg-black/40 backdrop-blur-md">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-brand-500/10 border border-brand-500/20 p-2 rounded-lg">
                <Aperture className="text-brand-400 w-6 h-6" />
            </div>
            <span className="text-xl font-bold tracking-tight text-white font-mono">TrueSight<span className="text-brand-500">_AI</span></span>
          </div>
          <div className="flex items-center gap-6">
            <div className="hidden md:flex items-center gap-6 text-sm font-medium text-gray-400">
                <span className="hover:text-brand-400 transition-colors cursor-pointer">Forensics</span>
                <span className="hover:text-brand-400 transition-colors cursor-pointer">Research</span>
            </div>
            <div className="h-4 w-px bg-gray-800 hidden md:block"></div>
            <a href="#" className="text-gray-400 hover:text-white transition-colors">
                <Github className="w-5 h-5" />
            </a>
          </div>
        </div>
      </nav>

      {/* Main Content */}
