                        onClick={capturePhoto} 
                        className="w-20 h-20 rounded-full border-4 border-white/20 flex items-center justify-center hover:bg-white/5 hover:border-white transition-all group"
                    >
                        <div className="w-16 h-16 bg-white rounded-full group-hover:scale-90 transition-transform"></div>
                    </button>
                </div>
            </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState, useCallback, useRef } from 'react';
import Dropzone from './components/Dropzone';
import ResultsDashboard from './components/ResultsDashboard';
import ScanningOverlay from './components/ScanningOverlay';
import { analyzeMediaIntegrity } from './services/geminiService';
import { AppState, AnalysisResult } from './types';
import { Aperture, Github, X, Sparkles } from 'lucide-react';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [showCamera, setShowCamera] = useState(false);
  const [caseId, setCaseId] = useState<string>("");

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // File processing
  const processFile = useCallback((file: File) => {
    const reader = new FileReader();
    reader.onload = async (e) => {
      if (e.target?.result) {
        const base64 = e.target.result as string;
        setSelectedImage(base64);
        runAnalysis(base64.split(',')[1]); // Remove data:image/type;base64,
      }
    };
    reader.readAsDataURL(file);
  }, []);

  // Analysis Logic
  const runAnalysis = async (base64Data: string) => {
    const newCaseId = Math.random().toString(36).substring(2, 10).toUpperCase();
    setCaseId(newCaseId);
    setAppState(AppState.ANALYZING);
    setErrorMsg(null);
    try {
      const data = await analyzeMediaIntegrity(base64Data);
      setResult(data);
      setAppState(AppState.RESULT);
    } catch (err) {
      console.error(err);
      setErrorMsg("Analysis failed. Please ensure the image is valid and try again.");
      setAppState(AppState.ERROR);
    }
  };

  const handleReset = () => {
    setAppState(AppState.IDLE);
    setSelectedImage(null);
    setResult(null);
    setErrorMsg(null);
    setCaseId("");
  };

  // Camera Handling
  const startCamera = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      console.error("Camera access denied:", err);
      alert("Could not access camera. Please allow permissions.");
      setShowCamera(false);
    }
  };

  const stopCamera = () => {
     if (videoRef.current && videoRef.current.srcObject) {
         const stream = videoRef.current.srcObject as MediaStream;
         stream.getTracks().forEach(track => track.stop());
         videoRef.current.srcObject = null;
     }
     setShowCamera(false);
  };

  const capturePhoto = () => {
      if (videoRef.current && canvasRef.current) {
          const video = videoRef.current;
          const canvas = canvasRef.current;
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          if (ctx) {
              ctx.drawImage(video, 0, 0);
              const base64 = canvas.toDataURL('image/jpeg');
              setSelectedImage(base64);
              stopCamera();
              runAnalysis(base64.split(',')[1]);
          }
      }
  };

  return (
    <div className="min-h-screen text-gray-100 font-sans selection:bg-brand-500/30">

      {/* Background Ambience */}
      <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none">
        <div className="absolute top-0 left-1/4 w-[500px] h-[500px] bg-brand-900/10 rounded-full blur-[100px] mix-blend-screen animate-pulse-slow"></div>
        <div className="absolute bottom-0 right-1/4 w-[600px] h-[600px] bg-indigo-900/10 rounded-full blur-[120px] mix-blend-screen animate-pulse-slow" style={{ animationDelay: '2s' }}></div>
      </div>

      {/* Header */}
      <nav className="relative z-10 border-b border-white/5 bg-black/40 backdrop-blur-md">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-brand-500/10 border border-brand-500/20 p-2 rounded-lg">
                <Aperture className="text-brand-400 w-6 h-6" />
            </div>
            <span className="text-xl font-bold tracking-tight text-white font-mono">TrueSight<span className="text-brand-500">_AI</span></span>
          </div>
          <div className="flex items-center gap-6">
            <div className="hidden md:flex items-center gap-6 text-sm font-medium text-gray-400">
                <span className="hover:text-brand-400 transition-colors cursor-pointer">Forensics</span>
                <span className="hover:text-brand-400 transition-colors cursor-pointer">Research</span>
            </div>
            <div className="h-4 w-px bg-gray-800 hidden md:block"></div>
            <a href="#" className="text-gray-400 hover:text-white transition-colors">
                <Github className="w-5 h-5" />
            </a>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="relative z-10 px-6 py-12 md:py-20 flex flex-col items-center min-h-[calc(100vh-64px)]">

        {appState === AppState.IDLE && (
           <div className="w-full max-w-4xl mx-auto animate-fade-in text-center flex flex-col items-center">
              <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full border border-brand-500/20 bg-brand-950/30 text-brand-300 text-sm font-mono mb-8 backdrop-blur-sm">
                <Sparkles size={14} />
                <span>Powered by Gemini 3.0 Pro Vision</span>
              </div>

              <h1 className="text-5xl md:text-7xl font-bold text-white mb-6 tracking-tight leading-tight">
                Verify Reality in <br/>
                <span className="text-transparent bg-clip-text bg-gradient-to-r from-brand-400 via-cyan-400 to-teal-400">The AI Age</span>
              </h1>

              <p className="text-lg md:text-xl text-gray-400 mb-12 max-w-2xl mx-auto leading-relaxed">
                Advanced forensic analysis for detecting deepfakes, GAN-synthesized faces, and digital manipulation.
              </p>

              <Dropzone onFileSelect={processFile} onCameraSelect={startCamera} />
           </div>
        )}

        {appState === AppState.ANALYZING && selectedImage && (
            <div className="flex flex-col items-center w-full max-w-2xl animate-fade-in">
                <h2 className="text-2xl font-bold mb-8 flex items-center gap-3 font-mono">
                    <span className="relative flex h-3 w-3">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-brand-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-3 w-3 bg-brand-500"></span>
                    </span>
                    Forensic Scan in Progress
                </h2>
                <div className="relative w-full aspect-square md:aspect-video rounded-2xl overflow-hidden border border-brand-500/20 shadow-[0_0_50px_rgba(14,165,233,0.1)] bg-gray-900">
                    <img src={selectedImage} alt="Analysis Target" className="w-full h-full object-contain opacity-40 blur-sm" />
                    <ScanningOverlay />
                </div>
                <div className="mt-8 flex flex-col items-center gap-2">
                    <div className="font-mono text-xs text-brand-500/50 uppercase tracking-widest">Case ID</div>
                    <div className="font-mono text-lg text-brand-400 tracking-widest">{caseId}</div>
                </div>
            </div>
        )}

        {appState === AppState.RESULT && result && (
            <ResultsDashboard result={result} onReset={handleReset} caseId={caseId} />
        )}

        {appState === AppState.ERROR && (
            <div className="glass-panel p-12 rounded-3xl text-center max-w-lg border-danger-500/30">
                <div className="w-20 h-20 bg-danger-500/10 rounded-full flex items-center justify-center mx-auto mb-6">
                    <X className="w-10 h-10 text-danger-500" />
                </div>
                <h2 className="text-2xl font-bold text-white mb-2">Analysis Interrupted</h2>
                <p className="text-gray-400 mb-8">{errorMsg}</p>
                <button 
                    onClick={handleReset} 
                    className="px-6 py-2 bg-gray-800 hover:bg-gray-700 text-white rounded-lg transition-colors border border-white/10"
                >
                    Return to Dashboard
                </button>
            </div>
        )}

      </main>

      {/* Camera Modal */}
      {showCamera && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/95 backdrop-blur-md p-4 animate-fade-in">
            <div className="bg-gray-900 border border-gray-800 rounded-3xl overflow-hidden max-w-2xl w-full relative shadow-2xl">
                <div className="p-4 border-b border-gray-800 flex justify-between items-center bg-gray-950">
                    <h3 className="font-semibold text-white font-mono flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>
                        LIVE FEED
                    </h3>
                    <button onClick={stopCamera} className="text-gray-400 hover:text-white transition-colors"><X size={20} /></button>
                </div>
                <div className="relative aspect-video bg-black">
                    <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover"></video>
                    <canvas ref={canvasRef} className="hidden"></canvas>

                    {/* Camera Overlay Elements */}
                    <div className="absolute inset-0 border-[20px] border-black/20 pointer-events-none"></div>
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-16 h-16 border-2 border-white/30 rounded-full pointer-events-none"></div>
                    <div className="absolute bottom-4 left-4 text-xs font-mono text-white/50">ISO AUTO</div>
                </div>
                <div className="p-8 flex justify-center bg-gray-950 border-t border-gray-800">
                    <button 
                        onClick={capturePhoto} 
                        className="w-20 h-20 rounded-full border-4 border-white/20 flex items-center justify-center hover:bg-white/5 hover:border-white transition-all group"
                    >
                        <div className="w-16 h-16 bg-white rounded-full group-hover:scale-90 transition-transform"></div>
                    </button>
                </div>
            </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React from 'react';
import { AnalysisResult } from '../types';
import { ShieldCheck, ShieldAlert, AlertTriangle, FileText, Activity, Zap, Eye, Layers, ScanFace, Download } from 'lucide-react';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, ResponsiveContainer } from 'recharts';

interface ResultsDashboardProps {
  result: AnalysisResult;
  onReset: () => void;
  caseId: string;
}

const ResultsDashboard: React.FC<ResultsDashboardProps> = ({ result, onReset, caseId }) => {
  const isReal = result.verdict === 'REAL';
  const isFake = result.verdict === 'FAKE';
  const colorClass = isReal ? 'text-accent-400' : isFake ? 'text-danger-400' : 'text-yellow-400';
  const bgClass = isReal ? 'bg-accent-500' : isFake ? 'bg-danger-500' : 'bg-yellow-500';

  const chartData = [
    { subject: 'Light', A: result.technicalMetrics.lightingConsistency, fullMark: 10 },
    { subject: 'Texture', A: result.technicalMetrics.textureNaturalness, fullMark: 10 },
    { subject: 'Anatomy', A: result.technicalMetrics.anatomyCorrectness, fullMark: 10 },
    { subject: 'Context', A: result.technicalMetrics.backgroundCoherence, fullMark: 10 },
  ];

  // Circular progress calculation
  const radius = 60;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (result.score / 100) * circumference;

  const handleDownloadReport = () => {
    const date = new Date().toLocaleString();
    const reportContent = `
================================================================
              TRUESIGHT AI // FORENSIC ANALYSIS REPORT
================================================================
CASE ID      : ${caseId}
DATE         : ${date}
VERDICT      : ${result.verdict}
TRUST SCORE  : ${result.score}/100
================================================================

[ EXECUTIVE SUMMARY ]
${result.summary}

[ DETECTED ARTIFACTS ]
${result.artifacts.map(a => `- ${a}`).join('\n')}

[ TECHNICAL METRICS ]
- Lighting Consistency : ${result.technicalMetrics.lightingConsistency}/10
- Texture Naturalness  : ${result.technicalMetrics.textureNaturalness}/10
- Anatomy Correctness  : ${result.technicalMetrics.anatomyCorrectness}/10
- Background Coherence : ${result.technicalMetrics.backgroundCoherence}/10

[ REASONING ]
${result.reasoning}

================================================================
Generated by TrueSight AI Media Integrity System
Powered by Gemini 3.0 Pro Vision
================================================================
`;

    const blob = new Blob([reportContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `TrueSight-Case-${caseId}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="w-full max-w-5xl mx-auto space-y-8 animate-fade-in pb-12">

      {/* Header Verdict Section */}
      <div className="flex justify-between items-end pb-2 border-b border-white/10">
          <div>
            <div className="text-xs font-mono text-gray-500 mb-1">CASE ID: {caseId}</div>
            <h1 className="text-3xl font-bold text-white">Analysis Results</h1>
          </div>
          <button 
            onClick={handleDownloadReport}
            className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-sm text-gray-300 transition-colors"
          >
            <Download size={16} />
            Export Case File
          </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">

        {/* Score Card */}
        <div className="glass-panel p-8 rounded-2xl flex flex-col items-center justify-center relative overflow-hidden group">
            <div className={`absolute inset-0 opacity-5 ${bgClass}`}></div>

            {/* Circular Gauge */}
            <div className="relative w-40 h-40 mb-4">
                <svg className="w-full h-full -rotate-90" viewBox="0 0 140 140">
                    <circle cx="70" cy="70" r={radius} fill="none" stroke="#1f2937" strokeWidth="10" />
                    <circle 
                        cx="70" cy="70" r={radius} fill="none" 
                        stroke="currentColor" strokeWidth="10" strokeLinecap="round"
                        strokeDasharray={circumference} strokeDashoffset={strokeDashoffset}
                        className={`${colorClass} transition-all duration-1000 ease-out`}
                    />
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className={`text-4xl font-bold font-mono ${colorClass}`}>{result.score}</span>
                    <span className="text-xs text-gray-500 font-mono uppercase mt-1">Trust Score</span>
                </div>
            </div>

            <h2 className={`text-2xl font-bold tracking-widest uppercase ${colorClass}`}>
                {result.verdict}
            </h2>
        </div>

        {/* Summary Card */}
        <div className="md:col-span-2 glass-panel p-8 rounded-2xl flex flex-col justify-between">
             <div className="flex items-center gap-3 mb-4">
                <div className={`p-2 rounded-lg ${isReal ? 'bg-accent-500/10' : isFake ? 'bg-danger-500/10' : 'bg-yellow-500/10'}`}>
                    {isReal && <ShieldCheck className={`w-6 h-6 ${colorClass}`} />}
                    {isFake && <ShieldAlert className={`w-6 h-6 ${colorClass}`} />}
                    {!isReal && !isFake && <AlertTriangle className={`w-6 h-6 ${colorClass}`} />}
                </div>
                <h3 className="text-lg font-semibold text-white">Forensic Summary</h3>
             </div>
             <p className="text-gray-300 leading-relaxed text-lg border-l-2 border-white/10 pl-4">
                "{result.summary}"
             </p>
        </div>
      </div>

      {/* Technical Deep Dive */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

          {/* Radar Chart */}
          <div className="glass-panel p-6 rounded-2xl">
            <h4 className="text-sm font-mono text-gray-500 uppercase mb-6 flex items-center gap-2">
                <Activity size={16} /> Metric Analysis
            </h4>
            <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                <RadarChart cx="50%" cy="50%" outerRadius="70%" data={chartData}>
                    <PolarGrid stroke="#334155" />
                    <PolarAngleAxis dataKey="subject" tick={{ fill: '#94a3b8', fontSize: 12, fontWeight: 500 }} />
                    <Radar
                    name="Metrics"
                    dataKey="A"
                    stroke={isReal ? '#10b981' : isFake ? '#ef4444' : '#eab308'}
                    fill={isReal ? '#10b981' : isFake ? '#ef4444' : '#eab308'}
                    fillOpacity={0.4}
                    />
                </RadarChart>
                </ResponsiveContainer>
            </div>
             <div className="grid grid-cols-2 gap-4 mt-2">
                 <MetricRow label="Lighting" value={result.technicalMetrics.lightingConsistency} icon={<Zap size={14}/>} />
                 <MetricRow label="Texture" value={result.technicalMetrics.textureNaturalness} icon={<ScanFace size={14}/>} />
                 <MetricRow label="Anatomy" value={result.technicalMetrics.anatomyCorrectness} icon={<Eye size={14}/>} />
                 <MetricRow label="Background" value={result.technicalMetrics.backgroundCoherence} icon={<Layers size={14}/>} />
             </div>
          </div>

          {/* Evidence List */}
          <div className="glass-panel p-6 rounded-2xl flex flex-col">
            <h4 className="text-sm font-mono text-gray-500 uppercase mb-6 flex items-center gap-2">
                <FileText size={16} /> Detected Artifacts
            </h4>

            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar space-y-3">
                {result.artifacts.length > 0 ? (
                    result.artifacts.map((artifact, idx) => (
                        <div key={idx} className="bg-black/20 p-3 rounded-lg border border-white/5 flex gap-3 group hover:border-white/10 transition-colors">
                            <span className="text-danger-500 font-mono text-sm mt-0.5">0{idx + 1}</span>
                            <span className="text-gray-300 text-sm">{artifact}</span>
                        </div>
                    ))
                ) : (
                    <div className="flex flex-col items-center justify-center h-40 text-gray-500 gap-2">
                        <ShieldCheck size={32} className="opacity-20" />
                        <span className="text-sm">No significant manipulation traces found.</span>
                    </div>
                )}
            </div>

            <div className="mt-6 pt-6 border-t border-white/5">
                <h5 className="text-xs font-mono text-gray-500 uppercase mb-2">Reasoning Chain</h5>
                <p className="text-xs text-gray-400 font-mono leading-relaxed opacity-80">
                    {result.reasoning}
                </p>
            </div>
          </div>
      </div>

      <div className="flex justify-center pt-8">
        <button 
          onClick={onReset}
          className="group relative px-8 py-3 bg-brand-600 hover:bg-brand-500 text-white rounded-full font-medium transition-all shadow-[0_0_20px_rgba(2,132,199,0.4)] hover:shadow-[0_0_30px_rgba(2,132,199,0.6)] flex items-center gap-2 overflow-hidden"
        >
          <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/20 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000"></div>
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
          <span className="relative">Analyze New Subject</span>
        </button>
      </div>
    </div>
  );
};

const MetricRow = ({ label, value, icon }: { label: string, value: number, icon: any }) => (
    <div className="flex items-center justify-between p-2 rounded bg-white/5">
        <div className="flex items-center gap-2 text-gray-400 text-xs font-medium uppercase">
            {icon} {label}
        </div>
        <div className="flex items-center gap-2">
            <div className="w-16 h-1.5 bg-gray-700 rounded-full overflow-hidden">
                <div className="h-full bg-brand-500 rounded-full" style={{ width: `${value * 10}%` }}></div>
            </div>
            <span className="font-mono text-xs font-bold text-white w-6 text-right">{value}</span>
        </div>
    </div>
);

export default ResultsDashboard;
